 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The unaltered cells repeat a horizontal color cycle. Ignore zeros and
    # the marked main diagonal when estimating each column's base color.
    base = []
    for c in range(w):
        vals = [grid[r][c] for r in range(h) if r != c and grid[r][c] != 0]
        if not vals:
            vals = [grid[r][c] for r in range(h) if grid[r][c] != 0]
        base.append(Counter(vals).most_common(1)[0][0])
    period = next((p for p in range(1, w + 1)
                   if all(base[c] == base[c % p] for c in range(w))), w)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            if r == c:
                row.append(base[(c - 1) % period])
            else:
                row.append(base[c])
        out.append(row)
    return out
